import{_ as t,c as a,o as h,a2 as i}from"./chunks/framework.B7el9cAC.js";const u=JSON.parse('{"title":"Mục 2.6 – Bảo Mật Thông Tin Trên Mạng","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.6-bao-mat-mang.md","filePath":"chuong-2/2.6-bao-mat-mang.md","lastUpdated":1775298974000}'),o={name:"chuong-2/2.6-bao-mat-mang.md"};function g(r,n,s,c,l,e){return h(),a("div",null,[...n[0]||(n[0]=[i(`<h1 id="muc-2-6-–-bao-mat-thong-tin-tren-mang" tabindex="-1">Mục 2.6 – Bảo Mật Thông Tin Trên Mạng <a class="header-anchor" href="#muc-2-6-–-bao-mat-thong-tin-tren-mang" aria-label="Permalink to &quot;Mục 2.6 – Bảo Mật Thông Tin Trên Mạng&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="tai-sao-can-bao-mat-thong-tin-tren-mang" tabindex="-1">Tại sao cần bảo mật thông tin trên mạng? <a class="header-anchor" href="#tai-sao-can-bao-mat-thong-tin-tren-mang" aria-label="Permalink to &quot;Tại sao cần bảo mật thông tin trên mạng?&quot;">​</a></h3><p>Hãy tưởng tượng bạn viết nhật ký và để lên bàn giữa phòng – ai đi qua cũng đọc được. Đó chính xác là điều xảy ra khi bạn gửi dữ liệu qua mạng <strong>mà không có bảo mật</strong>.</p><p>Trong thế giới số ngày nay:</p><ul><li>Thông tin cá nhân, tài khoản ngân hàng, mật khẩu của bạn đều đi qua mạng.</li><li>Có hàng triệu kẻ xấu (hacker, tội phạm mạng) đang chờ cơ hội đánh cắp.</li><li>Một vụ rò rỉ dữ liệu có thể gây thiệt hại tài chính, danh dự, thậm chí ảnh hưởng đến an ninh quốc gia.</li></ul><p><strong>Bảo mật thông tin</strong> là tập hợp các biện pháp kỹ thuật và phi kỹ thuật nhằm bảo vệ thông tin khỏi:</p><ul><li><strong>Truy cập trái phép</strong> (Unauthorized Access)</li><li><strong>Sửa đổi trái phép</strong> (Unauthorized Modification)</li><li><strong>Phá hoại, từ chối dịch vụ</strong> (Disruption/Denial)</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-cac-moi-đe-doa-bao-mat-pho-bien" tabindex="-1">2.1 Các mối đe dọa bảo mật phổ biến <a class="header-anchor" href="#_2-1-cac-moi-đe-doa-bao-mat-pho-bien" aria-label="Permalink to &quot;2.1 Các mối đe dọa bảo mật phổ biến&quot;">​</a></h3><h4 id="🦠-phan-mem-đoc-hai-malware" tabindex="-1">🦠 Phần mềm độc hại (Malware) <a class="header-anchor" href="#🦠-phan-mem-đoc-hai-malware" aria-label="Permalink to &quot;🦠 Phần mềm độc hại (Malware)&quot;">​</a></h4><p><strong>Malware (Malicious Software)</strong> là thuật ngữ chung chỉ mọi phần mềm được tạo ra với mục đích gây hại.</p><table tabindex="0"><thead><tr><th>Loại</th><th>Đặc điểm</th><th>Cách lây lan</th><th>Tác hại</th></tr></thead><tbody><tr><td><strong>Virus</strong></td><td>Gắn vào file, cần người dùng chạy để lây</td><td>File đính kèm email, USB</td><td>Xóa/sửa file, làm chậm máy</td></tr><tr><td><strong>Worm</strong></td><td>Tự nhân bản, lây qua mạng không cần người dùng</td><td>Lỗ hổng mạng, email</td><td>Chiếm băng thông, tắc nghẽn mạng</td></tr><tr><td><strong>Trojan</strong></td><td>Giả dạng phần mềm hợp lệ</td><td>Tải phần mềm lậu, crack</td><td>Mở cửa hậu cho hacker</td></tr><tr><td><strong>Ransomware</strong></td><td>Mã hóa dữ liệu, đòi tiền chuộc</td><td>Email, website giả</td><td>Mất dữ liệu, thiệt hại tài chính</td></tr><tr><td><strong>Spyware</strong></td><td>Theo dõi hoạt động người dùng ngầm</td><td>Phần mềm miễn phí không rõ nguồn</td><td>Đánh cắp mật khẩu, thói quen duyệt web</td></tr><tr><td><strong>Adware</strong></td><td>Hiển thị quảng cáo không mong muốn</td><td>Phần mềm miễn phí</td><td>Làm chậm máy, phiền nhiễu</td></tr></tbody></table><h4 id="🎣-tan-cong-phishing-gia-mao" tabindex="-1">🎣 Tấn công Phishing (Giả mạo) <a class="header-anchor" href="#🎣-tan-cong-phishing-gia-mao" aria-label="Permalink to &quot;🎣 Tấn công Phishing (Giả mạo)&quot;">​</a></h4><p><strong>Phishing</strong> là kỹ thuật <strong>giả mạo</strong> email, website, tin nhắn của tổ chức uy tín (ngân hàng, Google, Facebook...) để lừa người dùng cung cấp thông tin nhạy cảm.</p><p><strong>Dấu hiệu nhận biết Phishing:</strong></p><ul><li>URL lạ: <code>g00gle.com</code> thay vì <code>google.com</code>, <code>bank-vietcombank.net</code> thay vì <code>vietcombank.com.vn</code></li><li>Lỗi chính tả, ngữ pháp kém trong email.</li><li>Yêu cầu khẩn cấp: &quot;Tài khoản bạn sẽ bị khóa trong 24 giờ nếu không xác minh!&quot;</li><li>Yêu cầu cung cấp mật khẩu, mã OTP qua email/tin nhắn (ngân hàng thật <strong>không bao giờ</strong> hỏi điều này).</li></ul><h4 id="💥-tan-cong-ddos-tu-choi-dich-vu-phan-tan" tabindex="-1">💥 Tấn công DDoS (Từ chối dịch vụ phân tán) <a class="header-anchor" href="#💥-tan-cong-ddos-tu-choi-dich-vu-phan-tan" aria-label="Permalink to &quot;💥 Tấn công DDoS (Từ chối dịch vụ phân tán)&quot;">​</a></h4><p><strong>DDoS (Distributed Denial of Service)</strong> là tấn công làm cho máy chủ/website <strong>không thể phục vụ người dùng hợp lệ</strong> bằng cách gửi hàng triệu yêu cầu giả mạo cùng lúc.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Hacker]</span></span>
<span class="line"><span>    ↓ điều khiển</span></span>
<span class="line"><span>[Botnet – hàng nghìn máy tính bị nhiễm]</span></span>
<span class="line"><span>    ↓ tất cả gửi request đồng loạt</span></span>
<span class="line"><span>[Máy chủ mục tiêu] → QUÁ TẢI → SẬP</span></span></code></pre></div><p><strong>Hậu quả:</strong> Website/dịch vụ ngừng hoạt động. Thiệt hại: doanh nghiệp thương mại điện tử mất hàng trăm triệu đồng/giờ khi sập dịch vụ.</p><h4 id="👤-tan-cong-man-in-the-middle-mitm" tabindex="-1">👤 Tấn công Man-in-the-Middle (MITM) <a class="header-anchor" href="#👤-tan-cong-man-in-the-middle-mitm" aria-label="Permalink to &quot;👤 Tấn công Man-in-the-Middle (MITM)&quot;">​</a></h4><p>Kẻ tấn công <strong>chèn mình vào giữa</strong> hai bên giao tiếp, nghe lén và có thể sửa đổi dữ liệu mà cả hai bên không hay biết.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BẠN  ←→  [KẺ TẤN CÔNG]  ←→  NGÂN HÀNG</span></span>
<span class="line"><span>         (nghe lén tất cả,</span></span>
<span class="line"><span>          có thể sửa dữ liệu)</span></span></code></pre></div><p><strong>Xảy ra nhiều nhất khi:</strong> Dùng Wi-Fi công cộng không bảo mật. <strong>Phòng tránh:</strong> Dùng HTTPS, VPN.</p><h3 id="_2-2-cac-bien-phap-bao-mat" tabindex="-1">2.2 Các biện pháp bảo mật <a class="header-anchor" href="#_2-2-cac-bien-phap-bao-mat" aria-label="Permalink to &quot;2.2 Các biện pháp bảo mật&quot;">​</a></h3><h4 id="🔐-ma-hoa-du-lieu-encryption" tabindex="-1">🔐 Mã hóa dữ liệu (Encryption) <a class="header-anchor" href="#🔐-ma-hoa-du-lieu-encryption" aria-label="Permalink to &quot;🔐 Mã hóa dữ liệu (Encryption)&quot;">​</a></h4><p><strong>Mã hóa</strong> là quá trình <strong>biến dữ liệu dễ đọc thành dạng không đọc được</strong> (ciphertext) trừ khi có khóa giải mã.</p><p><strong>Ví dụ đơn giản (Caesar cipher):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Văn bản gốc: HELLO</span></span>
<span class="line"><span>Dịch chuyển 3: KHOOR</span></span>
<span class="line"><span>→ Nếu không có &quot;khóa&quot; (biết phải dịch lại 3), không đọc được</span></span></code></pre></div><p><strong>Mã hóa hiện đại:</strong></p><table tabindex="0"><thead><tr><th>Loại</th><th>Ví dụ</th><th>Đặc điểm</th></tr></thead><tbody><tr><td><strong>Đối xứng</strong> (Symmetric)</td><td>AES, DES</td><td>Cùng 1 khóa để mã hóa và giải mã – nhanh</td></tr><tr><td><strong>Bất đối xứng</strong> (Asymmetric)</td><td>RSA, ECC</td><td>Khóa công khai mã hóa, khóa riêng tư giải mã – an toàn hơn</td></tr><tr><td><strong>Hàm băm</strong> (Hash)</td><td>MD5, SHA-256</td><td>Một chiều, không giải mã được – dùng kiểm tra toàn vẹn</td></tr></tbody></table><p><strong>SSL/TLS</strong> (Secure Sockets Layer / Transport Layer Security) là giao thức mã hóa bảo vệ dữ liệu truyền giữa trình duyệt và máy chủ web – nền tảng của HTTPS.</p><h4 id="🧱-tuong-lua-firewall" tabindex="-1">🧱 Tường lửa (Firewall) <a class="header-anchor" href="#🧱-tuong-lua-firewall" aria-label="Permalink to &quot;🧱 Tường lửa (Firewall)&quot;">​</a></h4><p><strong>Firewall</strong> là hệ thống (phần cứng hoặc phần mềm) <strong>kiểm soát luồng dữ liệu</strong> vào/ra mạng, cho phép hoặc chặn dựa trên quy tắc được cấu hình.</p><ul><li><strong>Firewall phần cứng:</strong> Router cao cấp trong doanh nghiệp có tích hợp firewall.</li><li><strong>Firewall phần mềm:</strong> Windows Firewall, iptables trên Linux.</li></ul><p><strong>Nguyên tắc hoạt động:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Mạng ngoài/Internet]</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>     [FIREWALL]</span></span>
<span class="line"><span>     ├── Gói tin từ IP đáng tin cậy, cổng hợp lệ → CHO QUA ✅</span></span>
<span class="line"><span>     └── Gói tin từ IP lạ, cổng nguy hiểm, giao thức bị chặn → CHẶN ❌</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>     [Mạng nội bộ]</span></span></code></pre></div><p><strong>Bộ lọc firewall có thể dựa trên:</strong></p><ul><li>Địa chỉ IP nguồn/đích</li><li>Cổng nguồn/đích (port)</li><li>Giao thức (TCP, UDP, ICMP)</li><li>Nội dung gói tin (Deep Packet Inspection)</li></ul><h4 id="🛡️-phan-mem-diet-virus-antivirus-anti-malware" tabindex="-1">🛡️ Phần mềm diệt virus (Antivirus/Anti-malware) <a class="header-anchor" href="#🛡️-phan-mem-diet-virus-antivirus-anti-malware" aria-label="Permalink to &quot;🛡️ Phần mềm diệt virus (Antivirus/Anti-malware)&quot;">​</a></h4><p>Phần mềm antivirus hoạt động bằng cách:</p><ol><li><strong>Signature scanning:</strong> So sánh file với cơ sở dữ liệu virus đã biết.</li><li><strong>Heuristic analysis:</strong> Phân tích hành vi bất thường của file/chương trình.</li><li><strong>Sandboxing:</strong> Chạy file trong môi trường cách ly để quan sát hành vi.</li><li><strong>Real-time protection:</strong> Giám sát liên tục, cảnh báo ngay khi phát hiện mối đe dọa.</li></ol><p><strong>Phần mềm phổ biến:</strong> Kaspersky, BKAV (Việt Nam), Windows Defender, Bitdefender, Avast.</p><h4 id="🔑-xac-thuc-va-kiem-soat-truy-cap" tabindex="-1">🔑 Xác thực và kiểm soát truy cập <a class="header-anchor" href="#🔑-xac-thuc-va-kiem-soat-truy-cap" aria-label="Permalink to &quot;🔑 Xác thực và kiểm soát truy cập&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Phương pháp</th><th>Mô tả</th><th>Ví dụ</th></tr></thead><tbody><tr><td><strong>Mật khẩu</strong> (Password)</td><td>Thứ bạn <strong>biết</strong></td><td>Mật khẩu đăng nhập</td></tr><tr><td><strong>2FA/MFA</strong></td><td>Nhiều yếu tố xác thực</td><td>Mật khẩu + mã OTP SMS</td></tr><tr><td><strong>Sinh trắc học</strong> (Biometric)</td><td>Thứ bạn <strong>có</strong> (về sinh học)</td><td>Vân tay, khuôn mặt, mống mắt</td></tr><tr><td><strong>Certificate</strong></td><td>Chứng chỉ số</td><td>SSL Certificate, Smart Card</td></tr><tr><td><strong>SSO</strong></td><td>Đăng nhập một lần</td><td>&quot;Đăng nhập bằng Google&quot;</td></tr></tbody></table><p><strong>Nguyên tắc mật khẩu mạnh:</strong></p><ul><li>Ít nhất <strong>12 ký tự</strong> (khuyến nghị 15+ ký tự)</li><li>Kết hợp: chữ hoa, chữ thường, số, ký tự đặc biệt</li><li><strong>Không dùng</strong> tên, ngày sinh, &quot;123456&quot;, &quot;password&quot;</li><li><strong>Không dùng chung</strong> mật khẩu cho nhiều tài khoản</li><li>Thay đổi mật khẩu <strong>khi có dấu hiệu bị lộ</strong> (không nên đổi định kỳ theo lịch cố định vì thường dẫn đến mật khẩu yếu hơn)</li></ul><h3 id="_2-3-an-toan-khi-dung-mang" tabindex="-1">2.3 An toàn khi dùng mạng <a class="header-anchor" href="#_2-3-an-toan-khi-dung-mang" aria-label="Permalink to &quot;2.3 An toàn khi dùng mạng&quot;">​</a></h3><p><strong>Nguyên tắc vàng khi dùng Internet:</strong></p><ol><li><strong>Không chia sẻ thông tin cá nhân</strong> nhạy cảm (CMND, tài khoản ngân hàng, mật khẩu) qua mạng nếu không chắc chắn nơi nhận là an toàn.</li><li><strong>Kiểm tra HTTPS</strong> trước khi nhập mật khẩu hoặc thông tin thanh toán.</li><li><strong>Không tải phần mềm</strong> từ nguồn không rõ ràng – chỉ tải từ trang chính thức.</li><li><strong>Cập nhật phần mềm</strong> thường xuyên – bản vá bảo mật đóng các lỗ hổng mà hacker khai thác.</li><li><strong>Sao lưu dữ liệu</strong> định kỳ (backup) – đề phòng ransomware hoặc hỏng ổ cứng.</li><li><strong>Cẩn thận với Wi-Fi công cộng</strong> – tránh giao dịch nhạy cảm khi dùng Wi-Fi miễn phí.</li></ol><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="tai-sao-virus-khac-worm" tabindex="-1">Tại sao Virus khác Worm? <a class="header-anchor" href="#tai-sao-virus-khac-worm" aria-label="Permalink to &quot;Tại sao Virus khác Worm?&quot;">​</a></h3><p><strong>Virus</strong> cần &quot;ký chủ&quot; để tồn tại – giống như virus sinh học, nó gắn vào một file (ký chủ) và chờ người dùng chạy file đó để lây lan. Virus <strong>không tự lan</strong> – cần con người mang đi (copy file, gửi email).</p><p><strong>Worm</strong> tự di chuyển qua mạng – giống như sâu bọ bò, không cần ai giúp. Worm khai thác lỗ hổng mạng để tự sao chép sang máy tính khác mà không cần người dùng làm gì.</p><h3 id="tai-sao-can-2fa-xac-thuc-2-yeu-to" tabindex="-1">Tại sao cần 2FA (Xác thực 2 yếu tố)? <a class="header-anchor" href="#tai-sao-can-2fa-xac-thuc-2-yeu-to" aria-label="Permalink to &quot;Tại sao cần 2FA (Xác thực 2 yếu tố)?&quot;">​</a></h3><p>Mật khẩu có thể bị:</p><ul><li>Đoán (nếu yếu như &quot;123456&quot;)</li><li>Bị lộ qua phishing</li><li>Bị đánh cắp qua malware</li></ul><p>Nhưng nếu sau mật khẩu còn cần <strong>mã OTP gửi vào điện thoại của bạn</strong>, kẻ tấn công dù có mật khẩu cũng không thể đăng nhập nếu không có điện thoại bạn.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Chỉ mật khẩu:    Hacker biết mật khẩu → vào được ❌</span></span>
<span class="line"><span>Mật khẩu + OTP:  Hacker biết mật khẩu nhưng không có điện thoại bạn → không vào được ✅</span></span></code></pre></div><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="kich-ban-tan-cong-phishing-va-cach-phong-tranh" tabindex="-1">Kịch bản tấn công Phishing và cách phòng tránh <a class="header-anchor" href="#kich-ban-tan-cong-phishing-va-cach-phong-tranh" aria-label="Permalink to &quot;Kịch bản tấn công Phishing và cách phòng tránh&quot;">​</a></h3><p><strong>Kịch bản tấn công:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Bước 1] Hacker tạo website giả giống hệt trang ngân hàng VCB</span></span>
<span class="line"><span>          URL: vcb-bank.com.vn (giả) thay vì vietcombank.com.vn (thật)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 2] Hacker gửi email hàng loạt:</span></span>
<span class="line"><span>          &quot;⚠️ Tài khoản VCB của bạn có dấu hiệu đáng ngờ.</span></span>
<span class="line"><span>           Đăng nhập ngay để xác minh: [LINK]&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 3] Người dùng lo lắng → click vào link → vào trang giả</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 4] Nhập username + password + OTP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 5] Hacker nhận được thông tin, ngay lập tức dùng để đăng nhập vào VCB thật</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Bước 6] Chuyển tiền → Tiền mất!</span></span></code></pre></div><p><strong>Cách phòng tránh:</strong></p><ol><li>Luôn kiểm tra URL: <code>vietcombank.com.vn</code> ✅ vs <code>vcb-bank.com.vn</code> ❌</li><li>Không click link trong email – tự gõ địa chỉ vào trình duyệt.</li><li>Kích hoạt <strong>2FA</strong> – dù bị lộ mật khẩu, hacker cũng không vào được nếu cần OTP thứ 2.</li><li>Ngân hàng <strong>không bao giờ</strong> hỏi mật khẩu qua email/SMS.</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-nhan-biet-malware-trong-tinh-huong-thuc-te" tabindex="-1">Ví dụ 1 – Nhận biết malware trong tình huống thực tế <a class="header-anchor" href="#vi-du-1-–-nhan-biet-malware-trong-tinh-huong-thuc-te" aria-label="Permalink to &quot;Ví dụ 1 – Nhận biết malware trong tình huống thực tế&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tình huống</th><th>Loại malware</th></tr></thead><tbody><tr><td>Máy tính đột nhiên hiển thị thông báo &quot;Tất cả file của bạn đã bị mã hóa, trả 0.5 Bitcoin để lấy lại&quot;</td><td>Ransomware</td></tr><tr><td>Cài phần mềm tải nhạc miễn phí, máy tính bỗng chạy quảng cáo liên tục</td><td>Adware</td></tr><tr><td>Tải game crack, mật khẩu email bị thay đổi sau đó</td><td>Trojan/Spyware</td></tr><tr><td>Cả mạng trường học bị chậm do có máy tính liên tục gửi packet</td><td>Worm</td></tr><tr><td>Mở file đính kèm email, các file .docx bắt đầu bị xóa dần</td><td>Virus</td></tr></tbody></table><h3 id="vi-du-2-–-đanh-gia-đo-manh-cua-mat-khau" tabindex="-1">Ví dụ 2 – Đánh giá độ mạnh của mật khẩu <a class="header-anchor" href="#vi-du-2-–-đanh-gia-đo-manh-cua-mat-khau" aria-label="Permalink to &quot;Ví dụ 2 – Đánh giá độ mạnh của mật khẩu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mật khẩu</th><th>Đánh giá</th><th>Lý do</th></tr></thead><tbody><tr><td><code>123456</code></td><td>❌ Rất yếu</td><td>Quá đơn giản, trong top 10 mật khẩu phổ biến nhất</td></tr><tr><td><code>nguyenvana</code></td><td>❌ Yếu</td><td>Tên người dùng, dễ đoán</td></tr><tr><td><code>NguyenVanA1</code></td><td>⚠️ Trung bình</td><td>Có hoa thường số nhưng chứa tên</td></tr><tr><td><code>Tr@ng!2024#</code></td><td>✅ Khá mạnh</td><td>Hoa, thường, số, ký tự đặc biệt</td></tr><tr><td><code>xK9#mPq@7Yw!</code></td><td>✅✅ Rất mạnh</td><td>Ngẫu nhiên, dài 12+ ký tự, mọi loại ký tự</td></tr></tbody></table><h3 id="vi-du-3-–-firewall-rules-đon-gian" tabindex="-1">Ví dụ 3 – Firewall rules đơn giản <a class="header-anchor" href="#vi-du-3-–-firewall-rules-đon-gian" aria-label="Permalink to &quot;Ví dụ 3 – Firewall rules đơn giản&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Quy tắc Firewall của công ty ABC:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ALLOW  TCP  từ 192.168.1.0/24  đến bất kỳ   cổng 80,443   → Nhân viên duyệt web OK</span></span>
<span class="line"><span>ALLOW  TCP  từ bất kỳ          đến máy chủ   cổng 443      → Khách hàng vào website OK</span></span>
<span class="line"><span>DENY   TCP  từ bất kỳ          đến bất kỳ    cổng 22       → Chặn SSH từ ngoài</span></span>
<span class="line"><span>DENY   UDP  từ bất kỳ          đến bất kỳ    cổng 53       → Chặn DNS từ ngoài</span></span>
<span class="line"><span>DENY   tất cả từ ngoài đến mạng nội bộ                      → Chặn mọi truy cập còn lại</span></span></code></pre></div><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="cac-loai-malware" tabindex="-1">Các loại malware <a class="header-anchor" href="#cac-loai-malware" aria-label="Permalink to &quot;Các loại malware&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại</th><th>Tự lan qua mạng?</th><th>Cần file ký chủ?</th><th>Mục tiêu chính</th></tr></thead><tbody><tr><td><strong>Virus</strong></td><td>Không</td><td>Có</td><td>Phá hoại file</td></tr><tr><td><strong>Worm</strong></td><td>Có</td><td>Không</td><td>Lây lan, tắc nghẽn mạng</td></tr><tr><td><strong>Trojan</strong></td><td>Không</td><td>Giả làm phần mềm</td><td>Mở cửa hậu</td></tr><tr><td><strong>Ransomware</strong></td><td>Đôi khi</td><td>Không nhất thiết</td><td>Tống tiền</td></tr><tr><td><strong>Spyware</strong></td><td>Không</td><td>Không nhất thiết</td><td>Thu thập thông tin</td></tr></tbody></table><h3 id="phuong-phap-xac-thuc" tabindex="-1">Phương pháp xác thực <a class="header-anchor" href="#phuong-phap-xac-thuc" aria-label="Permalink to &quot;Phương pháp xác thực&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Phương pháp</th><th>Mức bảo mật</th><th>Tiện lợi</th><th>Ví dụ</th></tr></thead><tbody><tr><td>Mật khẩu đơn</td><td>⭐⭐</td><td>⭐⭐⭐⭐⭐</td><td>Đăng nhập cơ bản</td></tr><tr><td>Mật khẩu + OTP SMS</td><td>⭐⭐⭐⭐</td><td>⭐⭐⭐⭐</td><td>Ngân hàng online</td></tr><tr><td>Mật khẩu + Authenticator app</td><td>⭐⭐⭐⭐⭐</td><td>⭐⭐⭐</td><td>Gmail, GitHub</td></tr><tr><td>Vân tay/Khuôn mặt</td><td>⭐⭐⭐⭐</td><td>⭐⭐⭐⭐⭐</td><td>Điện thoại, laptop</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>🦠 <strong>Virus</strong> = bám vào file, cần người dùng chạy để lây; <strong>Worm</strong> = tự lan qua mạng</li><li>💰 <strong>Ransomware</strong> = mã hóa dữ liệu đòi tiền chuộc</li><li>🎣 <strong>Phishing</strong> = giả mạo tổ chức uy tín để đánh cắp thông tin</li><li>💥 <strong>DDoS</strong> = dùng nhiều máy tấn công cùng lúc → làm sập máy chủ</li><li>🧱 <strong>Firewall</strong> = kiểm soát luồng dữ liệu vào/ra mạng theo quy tắc</li><li>🔐 <strong>Mã hóa</strong> = biến dữ liệu thành dạng không đọc được nếu không có khóa</li><li>🔒 <strong>HTTPS</strong> = HTTP + mã hóa SSL/TLS → bảo vệ dữ liệu truyền tải</li><li>📱 <strong>2FA</strong> = xác thực 2 yếu tố = mật khẩu + OTP/sinh trắc học</li><li>🛡️ <strong>Antivirus</strong> = phát hiện và diệt malware (BKAV là phần mềm Việt Nam)</li><li>✅ Mật khẩu mạnh: <strong>dài 12+ ký tự</strong>, kết hợp hoa/thường/số/ký tự đặc biệt</li><li>❌ Không click link lạ trong email, SMS – dấu hiệu phishing</li><li>💾 Sao lưu dữ liệu thường xuyên để phòng ransomware</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-phan-loai-malware" tabindex="-1">Câu 1 (Dễ): Phân loại malware <a class="header-anchor" href="#cau-1-de-phan-loai-malware" aria-label="Permalink to &quot;Câu 1 (Dễ): Phân loại malware&quot;">​</a></h3><blockquote><p>Phần mềm nào sau đây <strong>tự lan sang máy tính khác qua mạng</strong> mà không cần người dùng thực hiện hành động? A. Virus B. Worm C. Trojan D. Adware</p></blockquote><p><strong>Đáp án: B – Worm</strong></p><p><strong>Giải thích:</strong> Worm (sâu máy tính) có khả năng tự nhân bản và lây lan qua mạng mà <strong>không cần người dùng thực hiện bất kỳ hành động nào</strong>. Nó khai thác lỗ hổng bảo mật của hệ điều hành hoặc ứng dụng mạng. Ngược lại, Virus cần gắn vào file và được người dùng chạy, Trojan giả mạo phần mềm hợp lệ, Adware hiển thị quảng cáo.</p><hr><h3 id="cau-2-de-nhan-biet-tan-cong" tabindex="-1">Câu 2 (Dễ): Nhận biết tấn công <a class="header-anchor" href="#cau-2-de-nhan-biet-tan-cong" aria-label="Permalink to &quot;Câu 2 (Dễ): Nhận biết tấn công&quot;">​</a></h3><blockquote><p>Bạn nhận được email từ &quot;<a href="mailto:support@g00gle.com" target="_blank" rel="noreferrer">support@g00gle.com</a>&quot; thông báo tài khoản Google sẽ bị xóa, yêu cầu click vào link để xác minh mật khẩu ngay lập tức. Đây là loại tấn công gì? Bạn nên làm gì?</p></blockquote><p><strong>Đáp án:</strong> Đây là tấn công <strong>Phishing</strong> (giả mạo).</p><p><strong>Dấu hiệu:</strong></p><ul><li>Email từ <code>g00gle.com</code> (dùng số 0 thay chữ o) – không phải <code>google.com</code></li><li>Tạo cảm giác khẩn cấp (&quot;tài khoản sẽ bị xóa&quot;)</li><li>Yêu cầu cung cấp mật khẩu</li></ul><p><strong>Cách xử lý:</strong></p><ol><li>Không click vào link.</li><li>Xóa email.</li><li>Nếu lo lắng, tự gõ <code>accounts.google.com</code> vào trình duyệt để kiểm tra tài khoản thật.</li><li>Báo email là spam/phishing cho nhà cung cấp email.</li></ol><hr><h3 id="cau-3-trung-binh-phan-tich-tinh-huong-bao-mat" tabindex="-1">Câu 3 (Trung bình): Phân tích tình huống bảo mật <a class="header-anchor" href="#cau-3-trung-binh-phan-tich-tinh-huong-bao-mat" aria-label="Permalink to &quot;Câu 3 (Trung bình): Phân tích tình huống bảo mật&quot;">​</a></h3><blockquote><p>Công ty A bị tấn công: website ngừng hoạt động 3 tiếng vì server nhận hàng triệu request từ hàng nghìn địa chỉ IP khác nhau trên toàn thế giới trong cùng một lúc. Đây là loại tấn công gì? Giải thích cơ chế.</p></blockquote><p><strong>Đáp án:</strong> Tấn công <strong>DDoS (Distributed Denial of Service)</strong>.</p><p><strong>Giải thích cơ chế:</strong></p><ul><li>Hacker kiểm soát một <strong>botnet</strong> (mạng lưới hàng nghìn/triệu máy tính đã bị nhiễm malware trên toàn thế giới).</li><li>Ra lệnh cho toàn bộ botnet gửi request đến server của công ty A cùng lúc.</li><li>Server bị <strong>quá tải</strong>, không thể xử lý request hợp lệ từ khách hàng thật → từ chối dịch vụ.</li><li>Vì request đến từ nhiều IP khác nhau (không phải một IP duy nhất), rất khó chặn.</li><li><strong>Đặc điểm nhận biết:</strong> Request đến từ hàng nghìn IP phân tán khắp thế giới, cùng một lúc, khác hành vi bình thường.</li></ul><hr><h3 id="cau-4-trung-binh-giai-thich-ma-hoa" tabindex="-1">Câu 4 (Trung bình): Giải thích mã hóa <a class="header-anchor" href="#cau-4-trung-binh-giai-thich-ma-hoa" aria-label="Permalink to &quot;Câu 4 (Trung bình): Giải thích mã hóa&quot;">​</a></h3><blockquote><p>Hãy giải thích tại sao cần dùng HTTPS thay vì HTTP khi truy cập trang web ngân hàng. Điều gì xảy ra nếu dùng HTTP?</p></blockquote><p><strong>Đáp án:</strong></p><p><strong>Nếu dùng HTTP (không mã hóa):</strong></p><ul><li>Dữ liệu truyền đi ở dạng <strong>văn bản thuần túy (plaintext)</strong>.</li><li>Bất kỳ ai có thể nghe lén mạng (ví dụ: kẻ tấn công trong cùng Wi-Fi) có thể đọc được: tên đăng nhập, mật khẩu, số tài khoản, số dư...</li><li>Trên Wi-Fi công cộng, kỹ thuật MITM (Man-in-the-Middle) cho phép kẻ tấn công đọc và thậm chí <strong>sửa đổi</strong> dữ liệu bạn gửi.</li></ul><p><strong>Tại sao HTTPS an toàn hơn:</strong></p><ul><li>Dữ liệu được <strong>mã hóa bằng TLS</strong> trước khi gửi đi.</li><li>Kẻ nghe lén chỉ thấy chuỗi ký tự vô nghĩa, không giải mã được nếu không có khóa.</li><li><strong>Xác thực máy chủ:</strong> HTTPS dùng chứng chỉ số (SSL Certificate) để chứng minh website là thật (không phải website giả mạo).</li></ul><hr><h3 id="cau-5-van-dung-thiet-ke-chinh-sach-bao-mat" tabindex="-1">Câu 5 (Vận dụng): Thiết kế chính sách bảo mật <a class="header-anchor" href="#cau-5-van-dung-thiet-ke-chinh-sach-bao-mat" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Thiết kế chính sách bảo mật&quot;">​</a></h3><blockquote><p>Bạn là quản trị viên IT của một trường học. Hãy đề xuất ít nhất <strong>5 biện pháp bảo mật</strong> để bảo vệ mạng và dữ liệu của trường. Giải thích lý do cho mỗi biện pháp.</p></blockquote><p><strong>Đáp án gợi ý:</strong></p><table tabindex="0"><thead><tr><th>STT</th><th>Biện pháp</th><th>Lý do</th></tr></thead><tbody><tr><td>1</td><td>Cài đặt Firewall tại cổng mạng</td><td>Ngăn chặn truy cập trái phép từ ngoài vào</td></tr><tr><td>2</td><td>Bắt buộc mật khẩu mạnh (8+ ký tự, phức tạp) cho tất cả tài khoản</td><td>Ngăn đoán/dò mật khẩu</td></tr><tr><td>3</td><td>Cài antivirus và cập nhật định kỳ trên mọi máy</td><td>Phát hiện và diệt malware</td></tr><tr><td>4</td><td>Sao lưu dữ liệu quan trọng hàng ngày (backup)</td><td>Phòng mất dữ liệu do ransomware, hỏng ổ cứng</td></tr><tr><td>5</td><td>Phân quyền truy cập: học sinh không được xóa file hệ thống</td><td>Ngăn vô tình hoặc cố ý phá hoại</td></tr><tr><td>6</td><td>Cập nhật hệ điều hành và phần mềm thường xuyên</td><td>Vá lỗ hổng bảo mật mà malware khai thác</td></tr><tr><td>7</td><td>Đào tạo nhận thức bảo mật cho giáo viên và học sinh</td><td>Phòng tránh phishing và social engineering</td></tr></tbody></table><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-virus-va-worm" tabindex="-1">❌ Lỗi 1: Nhầm Virus và Worm <a class="header-anchor" href="#❌-loi-1-nham-virus-va-worm" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm Virus và Worm&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Worm cần gắn vào file để lây lan.&quot;</p><p><strong>Đúng:</strong> <strong>Worm tự lây lan qua mạng</strong>, không cần file ký chủ, không cần người dùng thực hiện hành động. <strong>Virus</strong> mới cần gắn vào file và cần người dùng chạy file đó.</p><hr><h3 id="❌-loi-2-nghi-antivirus-la-đu-đe-bao-ve-hoan-toan" tabindex="-1">❌ Lỗi 2: Nghĩ Antivirus là đủ để bảo vệ hoàn toàn <a class="header-anchor" href="#❌-loi-2-nghi-antivirus-la-đu-đe-bao-ve-hoan-toan" aria-label="Permalink to &quot;❌ Lỗi 2: Nghĩ Antivirus là đủ để bảo vệ hoàn toàn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Máy tính có Antivirus là an toàn tuyệt đối.&quot;</p><p><strong>Đúng:</strong> Antivirus là lớp bảo vệ quan trọng nhưng <strong>không đủ một mình</strong>. Còn cần: Firewall, cập nhật phần mềm, mật khẩu mạnh, 2FA, và thói quen dùng mạng an toàn. Nhiều virus mới (zero-day) chưa có trong cơ sở dữ liệu antivirus.</p><hr><h3 id="❌-loi-3-nghi-phishing-chi-qua-email" tabindex="-1">❌ Lỗi 3: Nghĩ Phishing chỉ qua email <a class="header-anchor" href="#❌-loi-3-nghi-phishing-chi-qua-email" aria-label="Permalink to &quot;❌ Lỗi 3: Nghĩ Phishing chỉ qua email&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Phishing chỉ xảy ra qua email.&quot;</p><p><strong>Đúng:</strong> Phishing có thể qua <strong>email, SMS (smishing), điện thoại (vishing), mạng xã hội, quảng cáo website</strong>. Bất kỳ kênh nào có thể giả mạo tổ chức uy tín để lừa lấy thông tin đều là phishing.</p><hr><h3 id="❌-loi-4-nham-firewall-voi-antivirus" tabindex="-1">❌ Lỗi 4: Nhầm Firewall với Antivirus <a class="header-anchor" href="#❌-loi-4-nham-firewall-voi-antivirus" aria-label="Permalink to &quot;❌ Lỗi 4: Nhầm Firewall với Antivirus&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Firewall kiểm tra file xem có virus không.&quot;</p><p><strong>Đúng:</strong> <strong>Firewall kiểm soát luồng dữ liệu</strong> vào/ra mạng (dựa trên IP, port, giao thức). <strong>Antivirus quét file/chương trình</strong> để tìm malware. Đây là hai công cụ khác nhau, bổ sung cho nhau, không thay thế nhau.</p><hr><h3 id="❌-loi-5-nghi-mat-khau-dai-la-mat-khau-manh" tabindex="-1">❌ Lỗi 5: Nghĩ mật khẩu dài là mật khẩu mạnh <a class="header-anchor" href="#❌-loi-5-nghi-mat-khau-dai-la-mat-khau-manh" aria-label="Permalink to &quot;❌ Lỗi 5: Nghĩ mật khẩu dài là mật khẩu mạnh&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mật khẩu &#39;aaaaaaaaaaaa&#39; (12 chữ a) là mạnh vì dài 12 ký tự.&quot;</p><p><strong>Đúng:</strong> Độ mạnh của mật khẩu phụ thuộc vào <strong>độ phức tạp và tính ngẫu nhiên</strong>, không chỉ độ dài. <code>aaaaaaaaaaaa</code> cực kỳ yếu vì kẻ tấn công dùng <strong>dictionary attack</strong> (tấn công từ điển) sẽ thử ngay. Mật khẩu mạnh cần kết hợp: chữ HOA, chữ thường, SỐ, ký tự đặc biệt, VÀ không có nghĩa rõ ràng.</p>`,142)])])}const p=t(o,[["render",g]]);export{u as __pageData,p as default};
